default.nix
---DATA---
{
  "_meta": {
    "default": "0.16.0",
    "releases": "https://github.com/modem-dev/hunk/releases"
  },
  "0.16.0": {
    "x86_64-linux": { "sha256": "sha256-DdgMdnkmXfcmF4d6Atr+/WrGqDRSjhAldWdkLrLAXqY=" },
    "aarch64-linux": { "sha256": "sha256-fi5k7N7+x/REDACTED" },
    "x86_64-darwin": { "sha256": "REDACTED" },
    "aarch64-darwin": { "sha256": "REDACTED" }
  }
}
---NIX---
{ pkgs, lib, toolbox, toolboxLib }:

let
  inherit (toolboxLib.readData ./data.json) meta versions;

  assetPlatform = {
    "x86_64-linux" = "linux-x64";
    "aarch64-linux" = "linux-arm64";
    "x86_64-darwin" = "darwin-x64";
    "aarch64-darwin" = "darwin-arm64";
  }.${pkgs.stdenv.hostPlatform.system}
    or (throw "Unsupported system: ${pkgs.stdenv.hostPlatform.system}");

  builders = {
    default = version: versionData:
      let
        system = pkgs.stdenv.hostPlatform.system;
        platformData = versionData.${system}
          or (throw "hunk ${version} has no binary for ${system}");
      in
      pkgs.stdenv.mkDerivation {
        pname = "hunk";
        inherit version;

        src = pkgs.fetchurl {
          url = "https://github.com/modem-dev/hunk/releases/download/v${version}/hunkdiff-${assetPlatform}.tar.gz";
          hash = platformData.sha256;
        };

        sourceRoot = "hunkdiff-${assetPlatform}";

        dontConfigure = true;
        dontBuild = true;
        dontStrip = true;

        nativeBuildInputs = lib.optionals pkgs.stdenv.hostPlatform.isLinux [
          pkgs.autoPatchelfHook
        ];

        buildInputs = lib.optionals pkgs.stdenv.hostPlatform.isLinux [
          pkgs.stdenv.cc.cc.lib
        ];

        installPhase = ''
          runHook preInstall
          mkdir -p $out/bin
          install -m755 hunk $out/bin/hunk
          ln -s hunk $out/bin/hunkdiff
          runHook postInstall
        '';

        meta = with lib; {
          description = "Review-first terminal diff viewer for agentic coders";
          homepage = "https://github.com/modem-dev/hunk";
          license = licenses.mit;
          mainProgram = "hunk";
          platforms = [ "x86_64-linux" "aarch64-linux" "x86_64-darwin" "aarch64-darwin" ];
        };
      };
  };
in
{
  versions = toolboxLib.buildVersions "hunk" builders versions;
  default = meta.default;
}

